# Generated by FWShift: Windows Defender Firewall rules for one host, created with New-NetFirewallRule. Read the
# report first: what is not written is listed there.
#
#   powershell -ExecutionPolicy Bypass -File THIS_FILE -DryRun   shows what it would create (-WhatIf), creates nothing
#   powershell -ExecutionPolicy Bypass -File THIS_FILE           creates the rules (as administrator)
#
# -PolicyStore names another store than the local one (PersistentStore), such as a GPO: -PolicyStore 'example.com\GPO'.
# Every rule is created in the rule group FWShift; nothing is deleted and no profile setting is changed. A rule of
# that group, or of one of its names, stops the script before anything is created; a call Windows refuses stops it
# where it is. To take the rules away again: Remove-NetFirewallRule -Group 'FWShift'
#
# Windows evaluates these rules together with every other rule of the host: a block rule beats an allow rule, and
# what no rule matches gets the profile's default. Block rules are written without what the allow rules above them
# allowed in the source; see the report.
[CmdletBinding()]
param([switch]$DryRun, [string]$PolicyStore = 'PersistentStore')
Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$Group = 'FWShift'
$NamePrefix = 'FWShift-'
# The profiles in which the policy denies outbound connections no rule allows: their default must be Block.
$OutboundBlock = @('Domain', 'Private', 'Public')
$Created = 0
function Add-Rule([hashtable]$Rule) {
    if ($DryRun) { New-NetFirewallRule @Rule -Group $Group -PolicyStore $PolicyStore -WhatIf; return }
    $null = New-NetFirewallRule @Rule -Group $Group -PolicyStore $PolicyStore
    $script:Created++
}
if (-not $DryRun) {
    $taken = @(Get-NetFirewallRule -PolicyStore $PolicyStore -ErrorAction SilentlyContinue |
        Where-Object { $_.Group -eq $Group -or $_.Name -like ($NamePrefix + '*') })
    if ($taken.Count -gt 0) {
        throw ('rules of the group ' + $Group + ' or named ' + $NamePrefix + '... exist in ' + $PolicyStore + ' already (' +
            $taken[0].Name + '); nothing was created')
    }
}
foreach ($fwProfile in @(Get-NetFirewallProfile -PolicyStore ActiveStore)) {
    $name = [string]$fwProfile.Name
    if ([string]$fwProfile.Enabled -eq 'False') { Write-Warning ('the firewall is off in the profile ' + $name + ': no rule applies there') }
    if ([string]$fwProfile.DefaultInboundAction -eq 'Allow') {
        Write-Warning ('the profile ' + $name + ' allows inbound connections no rule blocks; this policy needs Block ' +
            '(Set-NetFirewallProfile -Name ' + $name + ' -DefaultInboundAction Block)')
    }
    if ($OutboundBlock -contains $name -and [string]$fwProfile.DefaultOutboundAction -ne 'Block') {
        Write-Warning ('the profile ' + $name + ' allows outbound connections that this policy denies; to deny them ' +
            'set Set-NetFirewallProfile -Name ' + $name + ' -DefaultOutboundAction Block')
    }
}

Add-Rule @{ Name = 'FWShift-Block_IoT_to_office-1'; DisplayName = 'Block_IoT_to_office (1)'; Description = 'FWShift: Block_IoT_to_office'; Direction = 'Inbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; LocalAddress = @('10.40.0.0/24'); RemoteAddress = @('10.41.0.0/24') }
Add-Rule @{ Name = 'FWShift-Block_IoT_to_office-2'; DisplayName = 'Block_IoT_to_office (2)'; Description = 'FWShift: Block_IoT_to_office'; Direction = 'Outbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; LocalAddress = @('10.41.0.0/24'); RemoteAddress = @('10.40.0.0/24') }
Add-Rule @{ Name = 'FWShift-Inside_Outside_web-1'; DisplayName = 'Inside_Outside_web (1)'; Description = 'FWShift: Inside_Outside_web'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('80', '443'); RemoteAddress = @('10.40.0.0/24') }
Add-Rule @{ Name = 'FWShift-Inside_Outside_web-2'; DisplayName = 'Inside_Outside_web (2)'; Description = 'FWShift: Inside_Outside_web'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'UDP'; LocalPort = @('53'); RemoteAddress = @('10.40.0.0/24') }
Add-Rule @{ Name = 'FWShift-Inside_Outside_web-3'; DisplayName = 'Inside_Outside_web (3)'; Description = 'FWShift: Inside_Outside_web'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('80', '443'); LocalAddress = @('10.40.0.0/24') }
Add-Rule @{ Name = 'FWShift-Inside_Outside_web-4'; DisplayName = 'Inside_Outside_web (4)'; Description = 'FWShift: Inside_Outside_web'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'UDP'; RemotePort = @('53'); LocalAddress = @('10.40.0.0/24') }
Add-Rule @{ Name = 'FWShift-NAS_from_Internet-1'; DisplayName = 'NAS_from_Internet (1)'; Description = 'FWShift: NAS_from_Internet'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; LocalPort = @('5001'); LocalAddress = @('10.40.0.10') }
Add-Rule @{ Name = 'FWShift-NAS_from_Internet-2'; DisplayName = 'NAS_from_Internet (2)'; Description = 'FWShift: NAS_from_Internet'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('5001'); RemoteAddress = @('10.40.0.10') }
Add-Rule @{ Name = 'FWShift-DNS_answers-1'; DisplayName = 'DNS_answers (1)'; Description = 'FWShift: DNS_answers'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'UDP'; LocalPort = @('1024-65535'); RemotePort = @('53') }
Add-Rule @{ Name = 'FWShift-DNS_answers-2'; DisplayName = 'DNS_answers (2)'; Description = 'FWShift: DNS_answers'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'UDP'; LocalPort = @('53'); RemotePort = @('1024-65535') }
Add-Rule @{ Name = 'FWShift-Staff_streaming-1'; DisplayName = 'Staff_streaming (1)'; Description = 'FWShift: Staff_streaming'; Direction = 'Inbound'; Action = 'Block'; Enabled = 'False'; Profile = 'Any' }
Add-Rule @{ Name = 'FWShift-Staff_streaming-2'; DisplayName = 'Staff_streaming (2)'; Description = 'FWShift: Staff_streaming'; Direction = 'Outbound'; Action = 'Block'; Enabled = 'False'; Profile = 'Any' }
Add-Rule @{ Name = 'FWShift-Guests_by_time-1'; DisplayName = 'Guests_by_time (1)'; Description = 'FWShift: Guests_by_time'; Direction = 'Inbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'ICMPv4'; IcmpType = @('3:3'); RemoteAddress = @('10.40.0.200-10.40.0.220') }
Add-Rule @{ Name = 'FWShift-Guests_by_time-2'; DisplayName = 'Guests_by_time (2)'; Description = 'FWShift: Guests_by_time'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'ICMPv4'; IcmpType = @('3:3'); LocalAddress = @('10.40.0.200-10.40.0.220') }

# Not written:
#   rule IoT_telemetry: not written, see the report
#   rule Head_office_v6: not written, see the report

if (-not $DryRun) { Write-Host ('Done: ' + $Created + ' rules created in the group ' + $Group) }
